export const dynamic = "force-dynamic";

import { notFound } from "next/navigation";
import { formatDistanceToNow } from "date-fns";
import { Prism as SyntaxHighlighter } from "react-syntax-highlighter";
import { vscDarkPlus } from "react-syntax-highlighter/dist/esm/styles/prism";
import { CopyCodeButton } from "./copy-button";
import { supabase } from "@/lib/supabase";
import { Badge } from "@/components/ui/badge";

interface Props {
  params: Promise<{ id: string }>;
}

export default async function SnippetPage({ params }: Props) {
  const { id } = await params;

  // Supabase call directly in Server Component
  const { data: snippet, error } = await supabase
    .from("snippets")
    .select(
      `
      *,
      profiles (
        username,
        display_name
      )
      `
    )
    .eq("id", id)
    .single();

  // If there's an error (e.g. invalid UUID) or it's private/deleted
  if (error || !snippet || !snippet.is_public) {
    return (
      <div className="flex min-h-[50vh] flex-col items-center justify-center gap-4 text-center">
        <h1 className="text-3xl font-bold tracking-tight">Snippet not found</h1>
        <p className="text-muted-foreground">
          This snippet might be private, deleted, or the URL is incorrect.
        </p>
      </div>
    );
  }

  const authorName =
    snippet.profiles?.display_name ?? snippet.profiles?.username ?? "Unknown Author";

  return (
    <div className="container mx-auto max-w-4xl px-4 py-12">
      <div className="mb-8 space-y-4">
        {/* Header content */}
        <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
          <div className="space-y-1">
            <h1 className="text-3xl font-bold tracking-tight">{snippet.title}</h1>
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <span>by {authorName}</span>
              <span>•</span>
              <time dateTime={snippet.created_at}>
                {formatDistanceToNow(new Date(snippet.created_at), {
                  addSuffix: true,
                })}
              </time>
            </div>
          </div>
          <CopyCodeButton code={snippet.code} />
        </div>

        {/* Tags */}
        <div className="flex flex-wrap items-center gap-2">
          <Badge variant="secondary" className="font-mono">
            {snippet.language}
          </Badge>
          {snippet.tags?.map((tag: string) => (
            <Badge key={tag} variant="outline" className="text-xs">
              #{tag}
            </Badge>
          ))}
        </div>

        {/* Description */}
        {snippet.description && (
          <p className="text-muted-foreground max-w-3xl leading-relaxed">
            {snippet.description}
          </p>
        )}
      </div>

      {/* Code Region */}
      <div className="relative overflow-hidden rounded-lg border bg-[#1e1e1e] shadow-md">
        <div className="flex items-center justify-between border-b border-[#333] bg-[#252526] px-4 py-2 text-xs font-mono text-[#cccccc]">
          <span>{snippet.language}</span>
          <span className="opacity-50 text-[10px]">
            {snippet.code.split("\n").length} lines
          </span>
        </div>
        <SyntaxHighlighter
          language={snippet.language}
          style={vscDarkPlus}
          customStyle={{
            margin: 0,
            padding: "1.25rem",
            background: "transparent",
            fontSize: "0.875rem",
            lineHeight: "1.5",
          }}
          showLineNumbers={true}
          wrapLines={true}
          lineNumberStyle={{
            minWidth: "3em",
            paddingRight: "1em",
            color: "#6e7681",
            textAlign: "right",
          }}
        >
          {snippet.code}
        </SyntaxHighlighter>
      </div>
    </div>
  );
}

import { notFound } from "next/navigation";
import { supabase } from "@/lib/supabase";
import Navbar from "@/components/navbar/Navbar";
import SnippetGrid from "@/components/snippets/SnippetGrid";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Separator } from "@/components/ui/separator";

interface Props {
  params: Promise<{ username: string }>;
}

export default async function UserProfilePage({ params }: Props) {
  const { username } = await params;

  // 1. Fetch user by username
  const { data: profile, error } = await supabase
    .from("profiles")
    .select("*")
    .eq("username", username)
    .single();

  if (error || !profile) {
    return (
      <div className="flex min-h-screen flex-col items-center justify-center text-center">
        <h1 className="text-3xl font-bold tracking-tight">User not found</h1>
        <p className="text-muted-foreground">This user does not exist.</p>
      </div>
    );
  }

  // 2. Fetch logged-in user to pass to Navbar
  const {
    data: { user: currentUser },
  } = await supabase.auth.getUser();

  return (
    <div className="min-h-screen bg-background flex flex-col">
      <Navbar user={currentUser} />

      <main className="flex-1 container mx-auto px-4 py-8 max-w-5xl">
        {/* Profile Header */}
        <div className="flex flex-col items-center sm:flex-row sm:items-start gap-6 mb-8 mt-4">
          <Avatar className="h-24 w-24 border">
            <AvatarImage src={profile.avatar_url ?? undefined} />
            <AvatarFallback className="text-3xl bg-primary/10 text-primary">
              {profile.username.charAt(0).toUpperCase()}
            </AvatarFallback>
          </Avatar>

          <div className="flex flex-col items-center sm:items-start text-center sm:text-left space-y-2">
            <div>
              <h1 className="text-3xl font-bold">{profile.display_name || profile.username}</h1>
              <p className="text-lg text-muted-foreground">@{profile.username}</p>
            </div>
            {profile.bio && (
              <p className="text-muted-foreground max-w-md">{profile.bio}</p>
            )}
          </div>
        </div>

        <Separator className="my-8" />

        <div className="space-y-4">
          <h2 className="text-xl font-bold tracking-tight">Public Snippets</h2>
          {/* Reusing SnippetGrid but scoped to this user. 
              The grid automatically queries useSnippets and handles loading/empty states. 
              Since this is a public page, row-level security defaults to `is_public=true`
              unless currentUser == profile.id! */}
          <SnippetGrid userId={profile.id} />
        </div>
      </main>
    </div>
  );
}

"use client";

import { useSnippetStore } from "@/store/snippetStore";
import type { Snippet } from "@/types";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { formatDistanceToNow } from "date-fns";
import { Globe, Lock, Code2 } from "lucide-react";
// Minimal syntax highlighter for the card preview
import { Prism as SyntaxHighlighter } from "react-syntax-highlighter";
import { vscDarkPlus } from "react-syntax-highlighter/dist/esm/styles/prism";

export default function SnippetCard({ snippet }: { snippet: Snippet }) {
  const { setActiveSnippet } = useSnippetStore();

  const previewCode = snippet.code.split("\n").slice(0, 5).join("\n") + (snippet.code.split("\n").length > 5 ? "\n..." : "");

  return (
    <Card
      className="flex flex-col cursor-pointer hover:border-primary/50 transition-colors group overflow-hidden bg-card/50"
      onClick={() => setActiveSnippet(snippet.id)}
    >
      <CardHeader className="flex flex-row items-start justify-between space-y-0 pb-2">
        <div className="space-y-1 overflow-hidden">
          <CardTitle className="text-base font-semibold truncate" title={snippet.title}>
            {snippet.title}
          </CardTitle>
          <div className="flex items-center text-xs text-muted-foreground gap-2">
            <time dateTime={snippet.updated_at}>
              {formatDistanceToNow(new Date(snippet.updated_at), { addSuffix: true })}
            </time>
          </div>
        </div>
        <div className="flex items-center gap-2 flex-shrink-0" title={snippet.is_public ? "Public" : "Private"}>
          {snippet.is_public ? (
            <Globe className="h-4 w-4 text-muted-foreground" />
          ) : (
            <Lock className="h-4 w-4 text-muted-foreground" />
          )}
        </div>
      </CardHeader>

      <CardContent className="py-2 flex-grow">
        <div className="relative rounded-md overflow-hidden bg-[#1e1e1e] border h-32 text-xs">
          <div className="absolute top-0 right-0 px-2 py-1 bg-[#252526] text-muted-foreground border-b border-l rounded-bl-md text-[10px] uppercase font-bold z-10">
            {snippet.language}
          </div>
          <SyntaxHighlighter
            language={snippet.language}
            style={vscDarkPlus}
            customStyle={{
              margin: 0,
              padding: "1rem",
              background: "transparent",
              fontSize: "0.75rem",
              lineHeight: "1.5",
              height: "100%",
            }}
            wrapLines={false}
          >
            {previewCode}
          </SyntaxHighlighter>
          {/* Fading bottom edge */}
          <div className="absolute bottom-0 left-0 right-0 h-12 bg-gradient-to-t from-[#1e1e1e] to-transparent pointer-events-none" />
        </div>
      </CardContent>

      <CardFooter className="flex flex-wrap gap-2 pt-2">
        {snippet.tags.slice(0, 3).map((tag) => (
          <Badge key={tag} variant="secondary" className="text-[10px] px-1.5 py-0">
            {tag}
          </Badge>
        ))}
        {snippet.tags.length > 3 && (
          <span className="text-xs text-muted-foreground">+{snippet.tags.length - 3}</span>
        )}
      </CardFooter>
    </Card>
  );
}

